    void BuildMap()
    {
        var p = new Painter(World.W, 64); for (int x = 0; x < World.W; x++) for (int y = 0; y < 64; y++) { float ty = 36 + y * 90f / 64; int top = W.Top[x]; Col c; if (ty < top) { c = Col.Lerp(0xf0e2bc, 0xe4cfa0, y / 64f); float wx = x * 24, wy = ty * 24; foreach (var q in W.Pools) if (q.Kind != Water.Cave && wx > q.X0 * 24 && wx < q.X1 * 24 && wy > q.Surf && ty < top) c = q.Kind == Water.Sea ? 0x6aa4b4 : 0x7ab4c0; } else { var g = World.GrassCol(x); c = ty - top < 2 ? g.Shade(-.1f) : Col.Lerp(g, 0xa8835e, M.Clamp((ty - top) / 8)).Shade(.05f + M.Noise(x * .1f, y * .2f) * .1f); if (x < 158 || x > 1392) c = Col.Lerp(0xe3c98e, 0xb89a6a, M.Clamp((ty - top) / 16)); int iy = (int)ty; if (!W.Solid(x, iy) && W.WallAt(x, iy) != T.Air) c = 0x5a4a52; foreach (var q in W.Pools) if (q.Kind == Water.Cave && x > q.X0 && x < q.X1 && ty * 24 > q.Surf && !W.Solid(x, iy)) c = 0x4a9aa0; if (MathF.Abs(ty - top) < .8f) c = 0x4a3428; } p.Px[y * World.W + x] = c.Rl(); }
        p.View(1, 0, 0); var r = new Rng(3); for (int i = 0; i < 110; i++) { int x = r.I(160, 1390); if (W.PoolAt(x * 24, W.Top[x] * 24 - 4) != null || x is > 728 and < 795) continue; var b = World.BiomeAt(x); if (b is Biome.Meadow or Biome.Village or Biome.Lake && r.P(.7f)) continue; float y = (W.Top[x] - 36) * 64f / 90; p.Begin(); if (b == Biome.Highlands) p.Poly(new(x - 9, y), new(x, y - 7), new(x + 9, y)); else p.Ellipse(x, y - 3, 11, 3.6f); p.Shade(new Ink(b == Biome.Autumn ? (r.P(.5f) ? 0xd8843a : 0xc9a347) : b == Biome.Highlands ? 0x4f8058 : 0x6f9a46, 2, .5f, 1) { Ao = 0 }); } foreach (int x in new[] { 731, 743, 777, 790 }) { float y = (89 - 36) * 64f / 90; p.Begin().Rect(x - 7, y - 5, 14, 5); p.Shade(new Ink(0xf0e2c4, 1, .3f)); p.Begin().Poly(new(x - 10, y - 4), new(x, y - 10), new(x + 10, y - 4)); p.Shade(new Ink(0xb85a44, 1, .3f)); }
        map = p.ToTexture();
    }
