        (string n, float tx)[] pl = [("The West Sea", 46), ("Driftwood Beach", 124), ("Birchwood", 224), ("Maple River", 303), ("Amber Forest", 386), ("Lake Lantern", 536), ("Clover Meadow", 654), ("Lantern Village", 760), ("Rolling Hills", 990), ("Pinecrest Highlands", 1200), ("Sunrise Shore", 1404), ("The East Sea", 1468)]; for (int i = 0; i < pl.Length; i++) { bool kn = Store.Data.Areas.Contains(pl[i].n); float px = X(pl[i].tx * 24), py = y + mh + 12 + (i % 3) * 13; Raylib.DrawLineEx(new(px, Y(W.Top[(int)pl[i].tx] * 24) + 4), new(px, py), 1, new Color(120, 84, 60, 110)); string s = kn ? pl[i].n : "???"; float tw = Font.Width(s); Font.Draw(s, M.Clamp(px, x + tw / 2, x + w - tw / 2), py, kn ? Ui.Ink : Ui.Soft, 1, .5f); }
