    float titlePan = 700 * 24; bool titleSettings;
    void UpdateTitle(float dt)
    {
        titleT += dt; Env.Update(dt * .6f); if (panel == Panel.Settings && In.Press(Act.Menu) && rebinding == null) ClosePanel(); openT += dt; titlePan += dt * 13; if (titlePan > 1040 * 24) titlePan = 610 * 24; CamX = titlePan; float gy = 0; for (int i = 0; i < 26; i++) gy += W.Top[(int)(titlePan / 24) + i]; gy = gy / 26 * 24 - Ui.VH * .74f; CamY = titleT < .1f ? gy : M.Damp(CamY, gy, .6f, dt); Life.Update(dt, P, CamX, CamY, (int)Ui.VW, (int)Ui.VH); Emit(dt); Ambience(); Snd.Music("title"); P.P = new(-9999, -9999);
    }
